 "content": "def transform(grid):
    """Draw color-3 straight segments between aligned markers."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    marker = next(x for row in grid for x in row if x != background)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if grid[r1][c] != marker:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if grid[r][c1] != marker:
                        out[r][c1] = 3
    return out
